// Get incoming sensor data
let data = msg.payload;

// Validate incoming readings
if (!data ||
    typeof data.temperature !== "number" ||
    typeof data.pressure !== "number" ||
    typeof data.humidity !== "number") {
    node.warn("Invalid BME280 sensor data");
    return null;
}

// Extract readings
let temperature = data.temperature;
let pressure = data.pressure;
let humidity = data.humidity;

// Generate basic recommendations
let recommendation = "";

if (temperature >= 35) {
    recommendation = "High temperature detected";
}
else if (humidity >= 75) {
    recommendation = "High humidity detected";
}
else if (temperature <= 20) {
    recommendation = "Low temperature detected";
}
else {
    recommendation = "Environmental conditions are normal";
}

// Prepare processed output
msg.payload = {
    temperature: temperature,
    pressure: pressure,
    humidity: humidity,
    recommendation: recommendation,
    timestamp: new Date().toISOString()
};

return msg;

