// INDUSTRIAL RECOMMENDATION ENGINE
// Demo use case: electronics component storage (thresholds are illustrative, not certified)
// Runs on: (a) every BME280 reading  (b) weather-comparison message (re-evaluates latest reading)

// ================= CONFIG (tune thresholds here only) =================
const CFG = {
    temp:      { low: 18, targetMax: 25, watchMax: 28, critical: 32, edge: 1 },   // °C
    hum:       { low: 30, targetMax: 50, watchMax: 60, warnMax: 70 },             // %RH
    dewMargin: { critical: 2, warning: 4 },                                       // °C above dew point
    tempRate:  { watch: 0.2, rapid: 0.5 },                                        // °C per minute
    pressure:  { watch: 1, significant: 2, minSpanMin: 10 },                      // hPa per hour
    trendWindowMs: 120000,       // window used for temperature trend
    minTrendSpanMs: 20000,       // minimum time covered before a trend is trusted
    minTrendSamples: 3,
    pressureWindowMs: 3600000,   // 1 hour history for pressure trend
    historyMaxSamples: 4000
};

const SEV_TAG = ["INFO", "WATCH", "WARNING", "CRITICAL"];

// ================= HELPERS =================
function slopePerMin(samples, key) {            // least-squares slope, units per minute
    const n = samples.length;
    const t0 = samples[0].t;
    let sx = 0, sy = 0, sxx = 0, sxy = 0;
    for (const s of samples) {
        const x = (s.t - t0) / 60000;
        sx += x; sy += s[key]; sxx += x * x; sxy += x * s[key];
    }
    const d = n * sxx - sx * sx;
    return d === 0 ? null : (n * sxy - sx * sy) / d;
}

function dewPoint(t, rh) {                      // Magnus formula
    if (rh <= 0) return null;
    const a = 17.62, b = 243.12;
    const g = Math.log(rh / 100) + (a * t) / (b + t);
    return (b * g) / (a - g);
}

// ================= GET READING =================
const p = msg.payload || {};
const isLive = [p.temperature, p.humidity, p.pressure]
    .every(v => typeof v === "number" && isFinite(v));

const now = Date.now();
let history = flow.get("industrialHistory") || [];
let reading;

if (isLive) {
    reading = { temperature: p.temperature, humidity: p.humidity, pressure: p.pressure };
    history.push({ t: now, temperature: reading.temperature, humidity: reading.humidity, pressure: reading.pressure });
    history = history.filter(s => now - s.t <= CFG.pressureWindowMs);
    if (history.length > CFG.historyMaxSamples) {
        history = history.slice(history.length - CFG.historyMaxSamples);
    }
    flow.set("industrialHistory", history);
} else {
    reading = flow.get("latestBME280");
    if (!reading) {
        return null;
    }
}

const weather = flow.get("openWeatherData");    // optional, not required
const T = Number(reading.temperature);
const H = Number(reading.humidity);
const P = Number(reading.pressure);

// ================= RECOMMENDATIONS =================
let recs = [];
const add = (sev, text) => recs.push({ sev, text });

// --- Temperature level ---
if (T >= CFG.temp.critical) {
    add(3, `Temperature ${T.toFixed(1)}°C is critically high. Inspect cooling and move heat-sensitive components.`);
} else if (T > CFG.temp.watchMax) {
    add(2, `Temperature ${T.toFixed(1)}°C is above ${CFG.temp.watchMax}°C. Investigate cooling and storage conditions.`);
} else if (T > CFG.temp.targetMax) {
    add(1, `Temperature ${T.toFixed(1)}°C is above target (${CFG.temp.targetMax}°C). Monitor increasing storage temperature.`);
} else if (T < CFG.temp.low) {
    add(1, `Temperature ${T.toFixed(1)}°C is below ${CFG.temp.low}°C. Check whether storage temperature is too low for the stored components.`);
} else if (T > CFG.temp.targetMax - CFG.temp.edge) {
    add(1, `Temperature ${T.toFixed(1)}°C is within target but close to the upper limit (${CFG.temp.targetMax}°C).`);
} else if (T < CFG.temp.low + CFG.temp.edge) {
    add(1, `Temperature ${T.toFixed(1)}°C is within target but close to the lower limit (${CFG.temp.low}°C).`);
} else {
    add(0, `Temperature ${T.toFixed(1)}°C is within target range (${CFG.temp.low}-${CFG.temp.targetMax}°C).`);
}

// --- Temperature trend (what makes the engine react quickly) ---
const recent = history.filter(s => now - s.t <= CFG.trendWindowMs);
let tempRate = null;
if (recent.length >= CFG.minTrendSamples &&
    (recent[recent.length - 1].t - recent[0].t) >= CFG.minTrendSpanMs) {
    tempRate = slopePerMin(recent, "temperature");
}

if (tempRate === null) {
    add(0, "Collecting temperature trend data.");
} else {
    const r = tempRate;
    const ar = Math.abs(r);
    const dir = r > 0 ? "rising" : "falling";
    if (ar >= CFG.tempRate.rapid) {
        add(2, `Temperature ${dir} rapidly (${r.toFixed(2)}°C/min). Check for a heat source, HVAC fault or door/airflow change.`);
    } else if (ar >= CFG.tempRate.watch) {
        add(1, `Temperature ${dir} (${r.toFixed(2)}°C/min). Monitor the trend.`);
    } else {
        add(0, `Temperature stable (${r.toFixed(2)}°C/min).`);
    }

    // Early warning: projected limit crossing within 30 minutes
    if (r > 0.05 && T <= CFG.temp.watchMax) {
        const mins = (CFG.temp.watchMax - T) / r;
        if (mins <= 30) {
            add(1, `At the current rate, temperature may exceed ${CFG.temp.watchMax}°C in about ${Math.ceil(mins)} min.`);
        }
    }
    if (r < -0.05 && T >= CFG.temp.low) {
        const mins = (T - CFG.temp.low) / Math.abs(r);
        if (mins <= 30) {
            add(1, `At the current rate, temperature may fall below ${CFG.temp.low}°C in about ${Math.ceil(mins)} min.`);
        }
    }
}

// --- Humidity ---
if (H > CFG.hum.warnMax) {
    add(2, `Humidity ${H.toFixed(1)}% - high-moisture warning. Inspect packaging and dehumidification.`);
} else if (H > CFG.hum.watchMax) {
    add(2, `Humidity ${H.toFixed(1)}%. Review moisture-sensitive component storage.`);
} else if (H > CFG.hum.targetMax) {
    add(1, `Humidity ${H.toFixed(1)}%. Monitor moisture exposure.`);
} else if (H < CFG.hum.low) {
    add(1, `Humidity ${H.toFixed(1)}% is low. Check electrostatic discharge (ESD) precautions.`);
} else {
    add(0, `Humidity ${H.toFixed(1)}% is within target range (${CFG.hum.low}-${CFG.hum.targetMax}%).`);
}

// --- Condensation risk (temperature vs dew point) ---
const dp = dewPoint(T, H);
if (dp !== null) {
    const margin = T - dp;
    if (margin <= CFG.dewMargin.critical) {
        add(3, `Condensation risk: temperature is only ${margin.toFixed(1)}°C above the dew point (${dp.toFixed(1)}°C). Protect exposed components.`);
    } else if (margin <= CFG.dewMargin.warning) {
        add(2, `Condensation margin is ${margin.toFixed(1)}°C (dew point ${dp.toFixed(1)}°C). Avoid further cooling.`);
    }
}

if (tempRate !== null && tempRate <= -CFG.tempRate.watch && H > CFG.hum.targetMax) {
    add(2, "Cooling while humid. Condensation risk is increasing.");
}

// --- Combined condition ---
if (T > CFG.temp.watchMax && H > CFG.hum.warnMax) {
    add(3, "High temperature and humidity together. Inspect storage conditions immediately.");
}

// --- Pressure trend (hPa per hour, experimental) ---
const oldest = history[0];
if (isLive && oldest && oldest.t < now) {
    const spanMin = (now - oldest.t) / 60000;
    if (spanMin >= CFG.pressure.minSpanMin) {
        const change = (P - oldest.pressure) * 60 / spanMin;
        if (change < -CFG.pressure.significant) {
            add(1, `Significant pressure drop (${change.toFixed(1)} hPa/h). Check external weather conditions.`);
        } else if (change > CFG.pressure.significant) {
            add(1, `Significant pressure rise (+${change.toFixed(1)} hPa/h). Monitor conditions.`);
        } else if (change < -CFG.pressure.watch) {
            add(1, `Pressure falling (${change.toFixed(1)} hPa/h). Monitor atmospheric changes.`);
        } else {
            add(0, "Atmospheric pressure stable.");
        }
    }
}

// ================= STATUS + OUTPUT =================
const maxSev = recs.reduce((m, r) => Math.max(m, r.sev), 0);
const status = maxSev >= 3 ? "CRITICAL" : (maxSev === 2 ? "WARNING" : "NORMAL");

recs.sort((a, b) => b.sev - a.sev);             // most serious first (stable)

let tempDiff = null;
let humidityDiff = null;
if (weather) {
    tempDiff = Number((T - weather.temperature).toFixed(2));
    humidityDiff = Number((H - weather.humidity).toFixed(2));
}

msg.payload = {
    status: status,
    recommendations: recs.map(r => `[${SEV_TAG[r.sev]}] ${r.text}`),
    localTemperature: T,
    localHumidity: H,
    weatherFeelsLike: weather ? weather.feelsLike : null,
    temperatureDifference: tempDiff,
    humidityDifference: humidityDiff,
    temperatureTrend: tempRate === null ? null : Number(tempRate.toFixed(3)),
    dewPoint: dp === null ? null : Number(dp.toFixed(2)),
    timestamp: new Date().toISOString()
};

return msg;

let recommendations = msg.payload.recommendations;

msg.payload = recommendations.join("\n");

return msg;

let data = msg.payload;

if (!data) {
    return null;
}

msg.payload = {
    localTemperature: data.localTemperature.toFixed(2) + " °C",
    weatherTemperature: data.weatherTemperature.toFixed(2) + " °C",

    localHumidity: data.localHumidity.toFixed(2) + " %",
    weatherHumidity: data.weatherHumidity.toFixed(2) + " %",

    temperatureDifference:
        (data.temperatureDifference > 0 ? "+" : "") +
        data.temperatureDifference.toFixed(2) + " °C",

    humidityDifference:
        (data.humidityDifference > 0 ? "+" : "") +
        data.humidityDifference.toFixed(2) + " percentage points"
};

return msg;

let data = context.get("dashboardData") || {};
let p = msg.payload;

if (!p || typeof p !== "object") {
    return null;
}

// 1. Store recommendation engine output
if (Array.isArray(p.recommendations)) {
    data.analysis = p;
}

// 2. Store comparison output AND latest local sensor readings
else if (
    p.localTemperature !== undefined &&
    p.weatherTemperature !== undefined
) {
    data.comparison = p;

    // Update sensor values from the comparison engine
    data.sensor = {
        temperature: p.localTemperature,
        humidity: p.localHumidity,
        pressure: p.localPressure
    };
}

// 3. Store direct BME280 sensor output
else if (
    p.temperature !== undefined &&
    p.pressure !== undefined &&
    p.humidity !== undefined
) {
    data.sensor = p;
}

context.set("dashboardData", data);

// Wait until all required data is available
if (!data.sensor || !data.comparison || !data.analysis) {
    node.warn("Waiting for all dashboard data sources");
    return null;
}

let s = data.sensor;
let c = data.comparison;
let a = data.analysis;

msg.payload = {
    localTemperature: Number(s.temperature),
    localHumidity: Number(s.humidity),
    localPressure: Number(s.pressure),

    weatherTemperature: Number(c.weatherTemperature),
    weatherHumidity: Number(c.weatherHumidity),

    temperatureDifference: Number(c.temperatureDifference),
    humidityDifference: Number(c.humidityDifference),

    status: a.status,
    recommendations: a.recommendations,

    timestamp: new Date().toISOString()
};

return msg;
